    /**
     * HOOK 2: Workspace Telemetry Pipeline Stream Terminal
     * Binds WebSocket listeners and POST triggers without inline script bloat
     */
    const $telemetry = $('#telemetry-console');
    const $pipelineBtn = $('#trigger-pipeline-btn');

    // Create raw socket target connecting into Daphne's protocol router
    const wsScheme = window.location.protocol === "https:" ? "wss://" : "ws://";
    const socket = new WebSocket(wsScheme + window.location.host + "/ws/console/");

    // Handle incoming backend live log events
    socket.onmessage = function(event) {
        const payload = JSON.parse(event.data);
        let rawLine = payload.message;
        let formattedLine = rawLine;

        // Apply clean syntax color strings via Bootstrap core classes
        if (rawLine.includes("[FAIL]")) {
            formattedLine = `<span class="text-danger fw-bold">${rawLine}</span>`;
        } else if (rawLine.includes("[SUCCESS]")) {
            formattedLine = `<span class="text-success fw-bold">${rawLine}</span>`;
        } else if (rawLine.includes("[INFO]")) {
            formattedLine = `<span class="text-muted">${rawLine}</span>`;
        }

        // Output line changes and lock tracking pane to the bottom line height
        $telemetry.append("\n" + formattedLine);
        
        if ($telemetry.length) {
            $telemetry.scrollTop($telemetry[0].scrollHeight);
        }
    };

    // Close state handler layer 
    socket.onclose = function() {
        $telemetry.append('\n<span class="text-warning fw-bold">[SYSTEM] Connection stream disconnected.</span>');
    };

    // Dispatch background AJAX POST trigger targeting the new API routing node
    $pipelineBtn.on('click', function(e) {
        e.preventDefault();
        $telemetry.html('<span class="text-info fw-bold">[SYSTEM] Broadcasting thread start command...</span>');

        $.ajax({
            url: '/aurora/console/run/',
            method: 'POST',
            contentType: 'application/json',
            dataType: 'json',
            success: function(response) {
                if (response.status === 'started') {
                    $telemetry.append('\n<span class="text-info">[SYSTEM] Pipeline initialized inside memory scope. Monitoring updates...</span>');
                }
            },
            error: function(xhr) {
                let errorMsg = 'Pipeline thread initiation failed.';
                if (xhr.responseJSON && xhr.responseJSON.error) {
                    errorMsg = xhr.responseJSON.error;
                }
                $telemetry.append(`\n<span class="text-danger fw-bold">[API_ERR] ${errorMsg}</span>`);
            }
        });
    });
// ======================================================================
